// src/index.ts
import * as fs3 from "fs/promises";
import * as fsSync4 from "fs";
import {
  createAgentPlugin
} from "@tokentop/plugin-sdk";

// src/cache.ts
var sessionCache = {
  lastCheck: 0,
  lastResult: [],
  lastLimit: 0,
  lastSince: undefined
};
var CACHE_TTL_MS = 2000;
var SESSION_AGGREGATE_CACHE_MAX = 1e4;
var sessionAggregateCache = new Map;
function evictSessionAggregateCache() {
  if (sessionAggregateCache.size <= SESSION_AGGREGATE_CACHE_MAX)
    return;
  const entries = Array.from(sessionAggregateCache.entries());
  entries.sort((a, b) => a[1].lastAccessed - b[1].lastAccessed);
  const toEvict = entries.length - SESSION_AGGREGATE_CACHE_MAX;
  for (let i = 0;i < toEvict; i++) {
    sessionAggregateCache.delete(entries[i][0]);
  }
}
var sessionMetadataIndex = new Map;
function invalidateSessionCaches(sessionId) {
  sessionAggregateCache.delete(sessionId);
  sessionCache.lastCheck = 0;
}

// src/paths.ts
import * as os from "os";
import * as path from "path";
var OPENCODE_AUTH_PATH = path.join(os.homedir(), ".local/share/opencode/auth.json");
var OPENCODE_CONFIG_PATH = path.join(os.homedir(), ".config/opencode/opencode.json");
var OPENCODE_STORAGE_PATH = path.join(os.homedir(), ".local/share/opencode/storage");
var OPENCODE_SESSIONS_PATH = path.join(OPENCODE_STORAGE_PATH, "session");
var OPENCODE_MESSAGES_PATH = path.join(OPENCODE_STORAGE_PATH, "message");
var OPENCODE_PARTS_PATH = path.join(OPENCODE_STORAGE_PATH, "part");
var OPENCODE_DB_PATH = path.join(os.homedir(), ".local/share/opencode/opencode.db");

// src/utils.ts
import * as fs from "fs/promises";
async function readJsonFile(filePath) {
  try {
    const content = await fs.readFile(filePath, "utf-8");
    return JSON.parse(content);
  } catch {
    return null;
  }
}
function resolveEnvValue(value) {
  if (!value)
    return;
  const envMatch = value.match(/^\{env:(\w+)\}$/);
  if (envMatch && envMatch[1]) {
    return process.env[envMatch[1]];
  }
  return value;
}
function buildOAuthCredentials(accessToken, refreshToken, expiresAt, accountId) {
  const oauth = { accessToken };
  if (refreshToken !== undefined)
    oauth.refreshToken = refreshToken;
  if (expiresAt !== undefined)
    oauth.expiresAt = expiresAt;
  if (accountId !== undefined)
    oauth.accountId = accountId;
  return oauth;
}

// src/credentials.ts
function parseAuthEntry(entry) {
  if (entry.type === "api" && entry.key) {
    return { apiKey: entry.key, source: "opencode" };
  }
  if (entry.type === "oauth" && entry.access) {
    return {
      oauth: buildOAuthCredentials(entry.access, entry.refresh, entry.expires),
      source: "opencode"
    };
  }
  if (entry.type === "codex" && entry.accessToken) {
    return {
      oauth: buildOAuthCredentials(entry.accessToken, entry.refreshToken, entry.expiresAt, entry.accountId),
      source: "opencode"
    };
  }
  if (entry.type === "github" && entry.token) {
    return { apiKey: entry.token, source: "opencode" };
  }
  if (entry.type === "wellknown") {
    const apiKey = entry.token ?? entry.key;
    if (apiKey) {
      return { apiKey, source: "opencode" };
    }
  }
  return null;
}

// src/json-fallback.ts
import * as fs2 from "fs/promises";
import * as fsSync2 from "fs";
import * as path3 from "path";

// src/watcher.ts
import * as fsSync from "fs";
import * as path2 from "path";
var RECONCILIATION_INTERVAL_MS = 10 * 60 * 1000;
var sessionWatcher = {
  projectWatchers: new Map,
  rootWatcher: null,
  dirtyPaths: new Set,
  reconciliationTimer: null,
  started: false
};
var forceFullReconciliation = false;
function watchProjectDir(projectDirPath) {
  if (sessionWatcher.projectWatchers.has(projectDirPath))
    return;
  try {
    const watcher = fsSync.watch(projectDirPath, (_eventType, filename) => {
      if (filename?.endsWith(".json")) {
        const filePath = path2.join(projectDirPath, filename);
        sessionWatcher.dirtyPaths.add(filePath);
      }
    });
    sessionWatcher.projectWatchers.set(projectDirPath, watcher);
  } catch {}
}
function startSessionWatcher() {
  if (sessionWatcher.started)
    return;
  sessionWatcher.started = true;
  try {
    sessionWatcher.rootWatcher = fsSync.watch(OPENCODE_SESSIONS_PATH, (eventType, filename) => {
      if (eventType === "rename" && filename) {
        const projectDirPath = path2.join(OPENCODE_SESSIONS_PATH, filename);
        watchProjectDir(projectDirPath);
      }
    });
  } catch {}
  try {
    const entries = fsSync.readdirSync(OPENCODE_SESSIONS_PATH, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isDirectory()) {
        watchProjectDir(path2.join(OPENCODE_SESSIONS_PATH, entry.name));
      }
    }
  } catch {}
  sessionWatcher.reconciliationTimer = setInterval(() => {
    forceFullReconciliation = true;
  }, RECONCILIATION_INTERVAL_MS);
}
function stopSessionWatcher() {
  if (sessionWatcher.reconciliationTimer) {
    clearInterval(sessionWatcher.reconciliationTimer);
    sessionWatcher.reconciliationTimer = null;
  }
  for (const watcher of sessionWatcher.projectWatchers.values()) {
    watcher.close();
  }
  sessionWatcher.projectWatchers.clear();
  if (sessionWatcher.rootWatcher) {
    sessionWatcher.rootWatcher.close();
    sessionWatcher.rootWatcher = null;
  }
  sessionWatcher.dirtyPaths.clear();
  sessionWatcher.started = false;
}
function consumeForceFullReconciliation() {
  const value = forceFullReconciliation;
  if (forceFullReconciliation) {
    forceFullReconciliation = false;
  }
  return value;
}

// src/json-fallback.ts
var activityWatcher = {
  watcher: null,
  callback: null,
  seenParts: new Set,
  debounceTimer: null,
  pendingDirs: new Set,
  messageWatchers: new Map
};
async function processPartFile(partPath) {
  if (activityWatcher.seenParts.has(partPath))
    return;
  activityWatcher.seenParts.add(partPath);
  const part = await readJsonFile(partPath);
  if (!part || !part.tokens)
    return;
  const callback = activityWatcher.callback;
  if (!callback)
    return;
  const tokens = {
    input: part.tokens.input ?? 0,
    output: part.tokens.output ?? 0
  };
  if (part.tokens.reasoning !== undefined)
    tokens.reasoning = part.tokens.reasoning;
  if (part.tokens.cache?.read !== undefined)
    tokens.cacheRead = part.tokens.cache.read;
  if (part.tokens.cache?.write !== undefined)
    tokens.cacheWrite = part.tokens.cache.write;
  invalidateSessionCaches(part.sessionID);
  const update = {
    sessionId: part.sessionID,
    messageId: part.messageID,
    tokens,
    timestamp: Date.now()
  };
  callback(update);
}
async function scanMessageDir(msgDirPath) {
  try {
    const files = await fs2.readdir(msgDirPath);
    for (const file of files) {
      if (file.endsWith(".json")) {
        const partPath = path3.join(msgDirPath, file);
        await processPartFile(partPath);
      }
    }
  } catch {}
}
function watchMessageDir(msgDirPath) {
  if (activityWatcher.messageWatchers.has(msgDirPath))
    return;
  try {
    const watcher = fsSync2.watch(msgDirPath, async (eventType, filename) => {
      if (eventType === "rename" && filename?.endsWith(".json")) {
        const partPath = path3.join(msgDirPath, filename);
        setTimeout(() => {
          processPartFile(partPath);
        }, 50);
      }
    });
    activityWatcher.messageWatchers.set(msgDirPath, watcher);
    scanMessageDir(msgDirPath);
  } catch {}
}
function startActivityWatchJson(callback) {
  if (activityWatcher.watcher) {
    activityWatcher.callback = callback;
    return;
  }
  activityWatcher.callback = callback;
  activityWatcher.seenParts.clear();
  try {
    activityWatcher.watcher = fsSync2.watch(OPENCODE_PARTS_PATH, (eventType, filename) => {
      if (eventType === "rename" && filename?.startsWith("msg_")) {
        const msgDirPath = path3.join(OPENCODE_PARTS_PATH, filename);
        watchMessageDir(msgDirPath);
      }
    });
  } catch {}
}
function stopActivityWatchJson() {
  if (activityWatcher.debounceTimer) {
    clearTimeout(activityWatcher.debounceTimer);
    activityWatcher.debounceTimer = null;
  }
  for (const watcher of activityWatcher.messageWatchers.values()) {
    watcher.close();
  }
  activityWatcher.messageWatchers.clear();
  if (activityWatcher.watcher) {
    activityWatcher.watcher.close();
    activityWatcher.watcher = null;
  }
  activityWatcher.callback = null;
  activityWatcher.seenParts.clear();
  activityWatcher.pendingDirs.clear();
  stopSessionWatcher();
}
async function parseSessionsJson(options, ctx) {
  const limit = options.limit ?? 100;
  const since = options.since;
  try {
    await fs2.access(OPENCODE_STORAGE_PATH);
  } catch {
    ctx.logger.debug("No OpenCode storage directory found");
    return [];
  }
  startSessionWatcher();
  const now = Date.now();
  if (!options.sessionId && limit === sessionCache.lastLimit && now - sessionCache.lastCheck < CACHE_TTL_MS && sessionCache.lastResult.length > 0 && sessionCache.lastSince === since) {
    ctx.logger.debug("JSON: using cached sessions (within TTL)", { count: sessionCache.lastResult.length });
    return sessionCache.lastResult;
  }
  const dirtyPaths = new Set(sessionWatcher.dirtyPaths);
  sessionWatcher.dirtyPaths.clear();
  const needsFullStat = consumeForceFullReconciliation();
  if (needsFullStat) {
    ctx.logger.debug("JSON: full reconciliation sweep triggered");
  }
  const sessions = [];
  const sessionFiles = [];
  let statCount = 0;
  let statSkipCount = 0;
  let parseCount = 0;
  let dirtyHitCount = 0;
  const seenFilePaths = new Set;
  try {
    const projectDirs = await fs2.readdir(OPENCODE_SESSIONS_PATH, { withFileTypes: true });
    for (const projectDir of projectDirs) {
      if (!projectDir.isDirectory())
        continue;
      const projectPath = path3.join(OPENCODE_SESSIONS_PATH, projectDir.name);
      watchProjectDir(projectPath);
      const sessionEntries = await fs2.readdir(projectPath, { withFileTypes: true });
      for (const entry of sessionEntries) {
        if (!entry.isFile() || !entry.name.endsWith(".json"))
          continue;
        const sessionFilePath = path3.join(projectPath, entry.name);
        seenFilePaths.add(sessionFilePath);
        const isDirty = dirtyPaths.has(sessionFilePath);
        if (isDirty)
          dirtyHitCount++;
        const cached = sessionMetadataIndex.get(sessionFilePath);
        if (!isDirty && !needsFullStat && cached) {
          statSkipCount++;
          const session2 = cached.session;
          if (session2?.id) {
            if (options.sessionId && session2.id !== options.sessionId)
              continue;
            sessionFiles.push({ path: sessionFilePath, session: session2 });
          }
          continue;
        }
        statCount++;
        let mtimeMs;
        try {
          const stat2 = await fs2.stat(sessionFilePath);
          mtimeMs = stat2.mtimeMs;
        } catch {
          sessionMetadataIndex.delete(sessionFilePath);
          continue;
        }
        if (cached && cached.mtimeMs === mtimeMs) {
          const session2 = cached.session;
          if (session2?.id) {
            if (options.sessionId && session2.id !== options.sessionId)
              continue;
            sessionFiles.push({ path: sessionFilePath, session: session2 });
          }
          continue;
        }
        parseCount++;
        const session = await readJsonFile(sessionFilePath);
        if (session?.id) {
          sessionMetadataIndex.set(sessionFilePath, { mtimeMs, session });
          if (options.sessionId && session.id !== options.sessionId)
            continue;
          sessionFiles.push({ path: sessionFilePath, session });
        } else {
          sessionMetadataIndex.delete(sessionFilePath);
        }
      }
    }
  } catch (err) {
    ctx.logger.debug("JSON: failed to read session directories", { error: err });
    return sessions;
  }
  for (const cachedPath of sessionMetadataIndex.keys()) {
    if (!seenFilePaths.has(cachedPath)) {
      sessionMetadataIndex.delete(cachedPath);
    }
  }
  if (since) {
    for (let i = sessionFiles.length - 1;i >= 0; i--) {
      if (sessionFiles[i].session.time.updated < since) {
        sessionFiles.splice(i, 1);
      }
    }
  }
  sessionFiles.sort((a, b) => b.session.time.updated - a.session.time.updated);
  let aggregateCacheHits = 0;
  let aggregateCacheMisses = 0;
  for (const { session } of sessionFiles) {
    const cached = sessionAggregateCache.get(session.id);
    if (cached && cached.updatedAt === session.time.updated) {
      cached.lastAccessed = now;
      aggregateCacheHits++;
      sessions.push(...cached.usageRows);
      continue;
    }
    aggregateCacheMisses++;
    const messagesDir = path3.join(OPENCODE_MESSAGES_PATH, session.id);
    try {
      await fs2.access(messagesDir);
    } catch {
      continue;
    }
    const messageFiles = await fs2.readdir(messagesDir, { withFileTypes: true });
    const messageData = [];
    for (const msgFile of messageFiles) {
      if (!msgFile.isFile() || !msgFile.name.endsWith(".json"))
        continue;
      const msgPath = path3.join(messagesDir, msgFile.name);
      try {
        const stat2 = await fs2.stat(msgPath);
        messageData.push({ file: msgPath, mtime: stat2.mtimeMs });
      } catch {
        continue;
      }
    }
    messageData.sort((a, b) => b.mtime - a.mtime);
    const sessionUsageRows = [];
    for (const { file: msgPath } of messageData) {
      const message = await readJsonFile(msgPath);
      if (!message || message.role !== "assistant" || !message.tokens)
        continue;
      const providerId = message.providerID ?? message.model?.providerID ?? "unknown";
      const modelId = message.modelID ?? message.model?.modelID ?? "unknown";
      const usage = {
        sessionId: session.id,
        providerId,
        modelId,
        tokens: {
          input: message.tokens.input ?? 0,
          output: message.tokens.output ?? 0
        },
        timestamp: message.time.completed ?? message.time.created,
        sessionUpdatedAt: session.time.updated
      };
      if (session.title) {
        usage.sessionName = session.title;
      }
      if (message.tokens.cache?.read) {
        usage.tokens.cacheRead = message.tokens.cache.read;
      }
      if (message.tokens.cache?.write) {
        usage.tokens.cacheWrite = message.tokens.cache.write;
      }
      if (session.directory) {
        usage.projectPath = session.directory;
      }
      sessionUsageRows.push(usage);
    }
    sessionAggregateCache.set(session.id, {
      updatedAt: session.time.updated,
      usageRows: sessionUsageRows,
      lastAccessed: now
    });
    sessions.push(...sessionUsageRows);
  }
  evictSessionAggregateCache();
  if (!options.sessionId) {
    sessionCache.lastCheck = Date.now();
    sessionCache.lastResult = sessions;
    sessionCache.lastLimit = limit;
    sessionCache.lastSince = since;
  }
  ctx.logger.debug("JSON: parsed OpenCode sessions", {
    count: sessions.length,
    sessionFiles: sessionFiles.length,
    statChecks: statCount,
    statSkips: statSkipCount,
    jsonParses: parseCount,
    dirtyHits: dirtyHitCount,
    aggregateCacheHits,
    aggregateCacheMisses,
    metadataIndexSize: sessionMetadataIndex.size,
    aggregateCacheSize: sessionAggregateCache.size
  });
  return sessions;
}

// src/sqlite.ts
import { Database } from "bun:sqlite";
import * as fsSync3 from "fs";
var sqliteDb = null;
var sqliteChecked = false;
var sqliteOpenedAt = 0;
var WAL_RELEASE_INTERVAL_MS = 5 * 60 * 1000;
function getDb() {
  if (sqliteDb) {
    if (Date.now() - sqliteOpenedAt > WAL_RELEASE_INTERVAL_MS) {
      closeDb();
    } else {
      return sqliteDb;
    }
  }
  if (sqliteChecked && !sqliteDb)
    return null;
  try {
    if (!fsSync3.existsSync(OPENCODE_DB_PATH)) {
      sqliteChecked = true;
      return null;
    }
    sqliteDb = new Database(OPENCODE_DB_PATH, { readonly: true, create: false });
    sqliteOpenedAt = Date.now();
    stmts = null;
    return sqliteDb;
  } catch {
    sqliteChecked = true;
    return null;
  }
}
function closeDb() {
  if (sqliteDb) {
    try {
      sqliteDb.close();
    } catch {}
    sqliteDb = null;
    stmts = null;
  }
}
var stmts = null;
var stmtsDb = null;
function detectSchema(db) {
  const rows = db.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name IN ('session', 'message', 'part', 'session_v2', 'session_message')").all();
  const names = new Set(rows.map((row) => row.name));
  return {
    v1: names.has("session") && names.has("message"),
    v1Parts: names.has("part"),
    v2: names.has("session_v2") && names.has("session_message")
  };
}
var SESSION_COLUMNS = "id, project_id, title, directory, time_created, time_updated";
var V1_SOURCE = {
  sessionTable: "session",
  messageTable: "message",
  assistantFilter: "json_extract(m.data, '$.role') = 'assistant'",
  providerId: "coalesce(json_extract(m.data, '$.providerID'), json_extract(m.data, '$.model.providerID'))",
  modelId: "coalesce(json_extract(m.data, '$.modelID'), json_extract(m.data, '$.model.modelID'))"
};
var V2_SOURCE = {
  sessionTable: "session_v2",
  messageTable: "session_message",
  assistantFilter: "m.type = 'assistant'",
  providerId: "json_extract(m.data, '$.model.providerID')",
  modelId: "json_extract(m.data, '$.model.id')"
};
function prepareSource(db, source) {
  const messageSelect = `
    SELECT m.id, m.session_id,
      ${source.providerId} AS provider_id,
      ${source.modelId} AS model_id,
      json_extract(m.data, '$.tokens.input') AS tokens_input,
      json_extract(m.data, '$.tokens.output') AS tokens_output,
      json_extract(m.data, '$.tokens.cache.read') AS cache_read,
      json_extract(m.data, '$.tokens.cache.write') AS cache_write,
      coalesce(json_extract(m.data, '$.time.completed'), json_extract(m.data, '$.time.created'), m.time_created) AS timestamp
    FROM ${source.messageTable} m
    WHERE ${source.assistantFilter}
      AND json_extract(m.data, '$.tokens.input') IS NOT NULL`;
  return {
    allSessions: db.prepare(`SELECT ${SESSION_COLUMNS} FROM ${source.sessionTable}`),
    sessionsSince: db.prepare(`SELECT ${SESSION_COLUMNS} FROM ${source.sessionTable} WHERE time_updated > ?`),
    oneSession: db.prepare(`SELECT ${SESSION_COLUMNS} FROM ${source.sessionTable} WHERE id = ?`),
    sessionMessages: db.prepare(`${messageSelect} AND m.session_id IN (SELECT value FROM json_each(?))`),
    allMessages: db.prepare(messageSelect)
  };
}
function getStmts(db) {
  if (stmts && stmtsDb === db)
    return stmts;
  const schema = detectSchema(db);
  stmts = {
    schema,
    v1: schema.v1 ? prepareSource(db, V1_SOURCE) : null,
    v2: schema.v2 ? prepareSource(db, V2_SOURCE) : null,
    recentParts: schema.v1Parts ? db.prepare("SELECT id, message_id, session_id, time_created, data FROM part WHERE time_created > ? ORDER BY time_created ASC") : null,
    recentMessages: schema.v2 ? db.prepare(`
          SELECT id, session_id, time_created, time_updated,
            json_extract(data, '$.tokens.input') AS tokens_input,
            json_extract(data, '$.tokens.output') AS tokens_output,
            json_extract(data, '$.tokens.reasoning') AS tokens_reasoning,
            json_extract(data, '$.tokens.cache.read') AS cache_read,
            json_extract(data, '$.tokens.cache.write') AS cache_write,
            json_extract(data, '$.time.completed') AS time_completed,
            json_extract(data, '$.error') IS NOT NULL AS errored
          FROM session_message
          WHERE time_created > ? AND type = 'assistant'
          ORDER BY time_created ASC
        `) : null
  };
  stmtsDb = db;
  return stmts;
}
function loadSessionRows(s, sessionId, since) {
  const merged = new Map;
  for (const source of [s.v2, s.v1]) {
    if (!source)
      continue;
    let rows;
    if (sessionId) {
      rows = source.oneSession.all(sessionId);
    } else if (since) {
      rows = source.sessionsSince.all(since);
    } else {
      rows = source.allSessions.all();
    }
    for (const row of rows) {
      const existing = merged.get(row.id);
      if (!existing || row.time_updated > existing.time_updated) {
        merged.set(row.id, row);
      }
    }
  }
  return Array.from(merged.values()).sort((a, b) => b.time_updated - a.time_updated);
}
function loadMessageRows(s, sessionIds) {
  const seen = new Set;
  const merged = [];
  const idsParam = sessionIds ? JSON.stringify(sessionIds) : null;
  for (const source of [s.v2, s.v1]) {
    if (!source)
      continue;
    const rows = idsParam ? source.sessionMessages.all(idsParam) : source.allMessages.all();
    for (const row of rows) {
      if (seen.has(row.id))
        continue;
      seen.add(row.id);
      merged.push(row);
    }
  }
  return merged;
}
function parseSessionsSqlite(options, ctx, db = getDb()) {
  if (!db)
    return [];
  const since = options.since;
  const now = Date.now();
  if (!options.sessionId && now - sessionCache.lastCheck < CACHE_TTL_MS && sessionCache.lastResult.length > 0 && sessionCache.lastSince === since) {
    ctx.logger.debug("SQLite: using cached sessions (within TTL)", { count: sessionCache.lastResult.length });
    return sessionCache.lastResult;
  }
  try {
    const s = getStmts(db);
    const sessions = [];
    const sessionRows = loadSessionRows(s, options.sessionId, since);
    let aggregateCacheHits = 0;
    let aggregateCacheMisses = 0;
    const uncachedSessions = new Map;
    for (const row of sessionRows) {
      const cached = sessionAggregateCache.get(row.id);
      if (cached && cached.updatedAt === row.time_updated) {
        cached.lastAccessed = now;
        aggregateCacheHits++;
        sessions.push(...cached.usageRows);
      } else {
        aggregateCacheMisses++;
        uncachedSessions.set(row.id, row);
      }
